//! ⚡️ Lowpoly artifact — OpText/OpBinary codecs for `LowpolyMutation`. Mutation apply/inverse (via
//! `protocol::Mutation`/`protocol::SemanticMutation`, generated by `#[derive(dsl_derive::Mutations)]`
//! on the dispatch enum in `../../../🧬️schema/🧬️mutations/🦀️.rs`) is NOT this file's concern; this file only wires the
//! operation-log line/binary encodings. `LowpolyMutation` (via `CreateObject.object: LowpolyObject`)
//! transitively carries `LowpolyObject.mesh: Option<store::ArtifactChild<SemioMeshSnapshot>>`, and
//! `store::ArtifactChild<S>`'s `Serialize`/`Deserialize` derive is `#[cfg_attr(test, ...)]`-gated
//! (ticket `26/09/01/RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS` — `serde` survives
//! on that framework type only as a test-only round-trip oracle now). So `LowpolyMutation` itself
//! cannot derive `Serialize`/`Deserialize` outside `#[cfg(test)]` either, and this file's encoding
//! can no longer route `serde_json` directly over `Self` the way the sibling `shooting`/`playground`
//! facets do (their mutation enums never carry an `ArtifactChild` field). Instead this bridges
//! through the always-available `semio_framework_value::ToValue`/`FromValue` derive (which `ArtifactChild<S>` also
//! implements unconditionally, hand-written, in `store::🦀️.rs`) and the framework's own
//! `DslValue`↔`serde_json::Value` conversion (`🌱️value/🦀️.rs`): `print_op`/`encode_op` still emit
//! compact, declaration-order JSON text/bytes (`serde_json::Value` itself is always `Serialize`),
//! so `OpText`/`OpBinary`'s laws (`print_op` never contains `\n`; `parse_op(op.print_op()) == op`;
//! encoding is deterministic) hold exactly as before — only the path from `Self` to JSON changed.

#[cfg(test)]
use crate::schema::PixelRun;
use crate::schema::mutations::{LowpolyMutation};

//#region 📖️SemioGrammar
/// 📖️ Normative handcrafted text grammar for this facet (`dialect grammar`).
pub const COMPONENT_GRAMMAR_SEMIO: &str = include_str!("📖️.grammar.semio");
pub const COMPONENT_GRAMMAR_PATH: &str = concat!(module_path!(), "::📖️.grammar.semio");
//#endregion 📖️SemioGrammar

/// 📝️ Physical JSON operation lines with compact byte fields.
impl protocol::OpText for LowpolyMutation {
    fn parse_op(line: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        super::lowpoly_json_decode(line).map_err(|error| semio_framework_diagnostic::TextError::new(error.kind, error.to_string(), semio_framework_diagnostic::TextSpan::at(1, 1)))
    }
    fn print_op(&self) -> String { super::lowpoly_json_encode(self) }
}


